  const languageLabel = { de: "German Precision", en: "English Fluency" };
  const tierLabel = {
    de: ["Precise Everyday German", "Register & Collocation", "Professional & Academic Precision", "Argumentative Nuance", "Advanced Precision"],
    en: ["Natural Foundations", "Collocations & Phrasal Verbs", "Advanced Fluency", "Argumentative English", "Precision & Academic Nuance"]
  };

  function stablePick(bank, level, slot) {
    // 50 question slots per 10-level tier. A coprime stride walks the whole tier bank
    // before repeating, producing stable spiral review without adjacent duplicate level sets.
    const tier = Math.ceil(level / 10);
    const position = ((level - 1) % 10) * 5 + slot;
    const idx = (position * 7 + tier * 3) % bank.length;
    return bank[idx];
  }

  function build(language, source) {
    const levels = [];
    for (let level = 1; level <= 50; level += 1) {
      const tier = Math.ceil(level / 10);
      const bank = source[tier];
      const questions = Array.from({ length: 5 }, (_, slot) => {
        const item = stablePick(bank, level, slot);
        return { ...item, id: `${item.id}-l${level}-s${slot + 1}` };
      });
      levels.push({
        language,
        languageLabel: languageLabel[language],
        level,
        tier,
        tierLabel: tierLabel[language][tier - 1],
        questions
      });
    }
    return levels;
  }

  const levels = {
    de: build("de", german),
    en: build("en", english)
  };

  window.LIFE_RPG_WORD_LAB_LEVELS = levels;
